window.blogDetail = {"blogId":1512130832,"blogType":0,"pubTime":"2017-12-01 20:20","cate":"个人日记","cateHex":"b8f6c8cbc8d5bcc7","title":"我读红楼梦（26）第二十二回 听曲文宝玉悟禅机，是灯谜贾政悲谶语——“悟”与“执”","commentNum":1,"effect1":1024,"effect2":524294,"ar":0,"block":0,"inproc":false,"appeal":0,"abstract":"不知不觉，我们已经走过红楼1/4的路程。（以80回版本来说），在前面这1/4的章节里，我们看到了一个世家大族的繁华，也看到了隐藏在世家大族背后的势利和人情。在全书庞大的架构里，前面的21回只能算是事情的开端或者说序幕 ，而第22回，在我看来，是一个十分重要的枢纽。因为他是我们的主人公，贾宝玉，第一次“悟道”，也是作者再一次运用谶语进行暗示。虽然说前面的第五回作者已经把，书中人物的命运写在正副册上。...","artype":1,"arUins":"","blogid":1512130832,"voteids":0,"pubtime":1512130832,"replynum":1,"category":"个人日记","effect":1024,"exblogtype":0,"sus_flag":false,"friendrelation":[],"lp_type":0,"lp_id":0,"lp_style":0,"lp_flag":0,"orguin":619774944,"orgblogid":1512130832,"mention_uins":[],"attach":[],"comments":[{"id":1512183641,"postTime":1512183641,"effect":1024,"replyNum":0,"content":"@{uin:1247362220,nick:琥珀,who:1,auto:1}你是谁？我不认识 ","capacity":12094,"poster":{"id":"619774944","platform":1,"name":"秋天的怀念 ","emoji":[],"uin":"619774944"},"bmp":"08d015a10000c201","ismyreply":1,"replies":[]}],"html":"","custom_title":"我读红楼梦（26）第二十二回 听曲文宝玉悟禅机，是灯谜贾政悲谶语——“悟”与“执”","custom_html":"","uniKey":"http://user.qzone.qq.com/619774944/blog/1512130832"}